import {mood} from './engine.js';
const $=s=>document.querySelector(s),worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});
let ready=false,seed=null,searchId=0,recommendId=0,timer,displayed=[],collectionView=false,toastTimer;
let saved=[];try{saved=JSON.parse(localStorage.getItem('undertone-saved')||'[]');if(!Array.isArray(saved))saved=[];saved=saved.filter(t=>Array.isArray(t)&&t.length===17&&typeof t[0]==='string');}catch{}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palette=['#605e84','#6b805f','#9b6d56','#566b7f','#846e80','#8d845d'];
function cover(t){return `<div class="cover" style="--cover:${palette[[...t[0]].reduce((n,c)=>n+c.charCodeAt(0),0)%palette.length]}" aria-hidden="true">${escape(t[1].slice(0,1))}</div>`;}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2600);}
function updateSaved(){ $('#saved-count').textContent=saved.length;try{localStorage.setItem('undertone-saved',JSON.stringify(saved));}catch{toast('Storage unavailable. Collection lasts for this visit.');}}
function filterValues(){return {minBpm:Number($('#bpm-min').value),maxBpm:Number($('#bpm-max').value),mood:$('#mood').value,voice:$('#voice').value,genre:$('#genre').value,acoustic:$('#acoustic').checked,clean:$('#clean').checked,otherArtists:$('#other-artists').checked};}
function requestRecommendations(){if(!seed||!ready||collectionView)return;const filters=filterValues();if(filters.minBpm<0||filters.maxBpm>250||filters.minBpm>filters.maxBpm){$('#status').textContent='Use a BPM range between 0 and 250, with minimum ≤ maximum.';return;}$('#status').textContent='Finding your next feeling…';worker.postMessage({type:'recommend',id:++recommendId,seed,filters});}
function selectSong(t){searchId++;seed=t;collectionView=false;$('#search').value=t[1]+' — '+t[2].replaceAll(';',', ');$('#suggestions').hidden=true;$('#search').setAttribute('aria-expanded','false');$('#seed').hidden=false;$('#seed').innerHTML=cover(t)+`<div><small>YOUR STARTING POINT</small><h3>${escape(t[1])}</h3><p class="muted">${escape(t[2].replaceAll(';',', '))}</p></div><div class="seed-meta">${Math.round(t[8])} BPM · ${mood(t)}<br>${escape(t[6].slice(0,2).join(' / '))}</div>`;$('#results-title').textContent='On the same wavelength.';requestRecommendations();}
function showTracks(rows){displayed=rows.map(r=>r.track||r);$('#result-count').textContent=`${displayed.length} ${collectionView?'saved':'discoveries'}`;if(!displayed.length){$('#results').innerHTML=`<div class="empty"><h3>${collectionView?'Your collection starts here.':'No songs in this pocket of sound.'}</h3><p>${collectionView?'Save a discovery with the + button. It stays in this browser.':'Try a wider BPM range or fewer filters. Unknown vocal labels are excluded from vocal filters.'}</p></div>`;return;}$('#results').innerHTML=displayed.map((t,i)=>{const savedTrack=saved.some(s=>s[0]===t[0]);return `<article class="track"><span class="number">${String(i+1).padStart(2,'0')}</span>${cover(t)}<div class="track-info"><button class="track-title" data-seed="${i}" title="Find songs like ${escape(t[1])}">${escape(t[1])}${t[5]?' <span aria-label="Explicit">ᴱ</span>':''}</button><div class="artist">${escape(t[2].replaceAll(';',', '))}</div><div class="tags"><span class="tag">${mood(t)}</span><span class="tag">${escape(t[6][0])}</span>${t[12]>=.65?'<span class="tag">Acoustic</span>':''}</div></div><div class="bpm">${Math.round(t[8])}<small>BPM</small></div><a class="listen" href="https://open.spotify.com/track/${encodeURIComponent(t[0])}" target="_blank" rel="noopener" aria-label="Listen to ${escape(t[1])} on Spotify">Listen ↗</a><button class="save ${savedTrack?'saved':''}" data-save="${i}" aria-label="${savedTrack?'Remove':'Save'} ${escape(t[1])}" aria-pressed="${savedTrack}">${savedTrack?'✓':'+'}</button></article>`;}).join('');}
function runSearch(){if(!ready){$('#status').textContent='The catalogue is still loading. Please wait a moment.';return;}worker.postMessage({type:'search',id:++searchId,query:$('#search').value});}
worker.onmessage=({data:m})=>{if(m.type==='ready'){ready=true;$('#status').textContent=`Search ${m.count.toLocaleString()} songs. Select a recording to discover similar sounds.`;$('#catalog-count').textContent=`${m.count.toLocaleString()} SONGS · AUDIO FEATURE SIMILARITY`;for(const g of m.genres){const opt=document.createElement('option');opt.value=g;opt.textContent=g;$('#genre').append(opt);}if($('#search').value)runSearch();}if(m.type==='search'&&m.id===searchId){const el=$('#suggestions');el.hidden=false;$('#search').setAttribute('aria-expanded','true');el.innerHTML=m.results.length?m.results.map((t,i)=>`<button data-result="${i}"><span>${escape(t[1])}<br><small>${escape(t[2].replaceAll(';',', '))}</small></span><small>${Math.round(t[8])} BPM ↗</small></button>`).join(''):'<p class="empty">No match in this catalogue. Try the artist name or fewer words. The catalogue is historical and does not include every song.</p>';el.querySelectorAll('button').forEach(b=>b.onclick=()=>selectSong(m.results[Number(b.dataset.result)]));}if(m.type==='recommend'&&m.id===recommendId&&!collectionView){showTracks(m.results);$('#status').textContent='Ranked by audio-feature distance. Mood descriptions are estimates.';}if(m.type==='error'){ $('#status').textContent=m.message+' Refresh the page to try again.';}};
worker.onerror=()=>$('#status').textContent='Music engine could not start. Refresh the page to try again.';
$('#search').oninput=()=>{clearTimeout(timer);searchId++;if(!$('#search').value.trim()){$('#suggestions').hidden=true;$('#search').setAttribute('aria-expanded','false');return;}timer=setTimeout(runSearch,170);};$('#search-button').onclick=runSearch;
$('#search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();runSearch();}if(e.key==='ArrowDown'){$('#suggestions button')?.focus();e.preventDefault();}if(e.key==='Escape'){$('#suggestions').hidden=true;$('#search').setAttribute('aria-expanded','false');}};
$('#suggestions').onkeydown=e=>{if(e.key==='Escape'){$('#suggestions').hidden=true;$('#search').focus();}if(e.key==='ArrowDown'){e.preventDefault();document.activeElement.nextElementSibling?.focus();}if(e.key==='ArrowUp'){e.preventDefault();(document.activeElement.previousElementSibling||$('#search')).focus();}};
document.addEventListener('click',e=>{if(!e.target.closest('.search-section')){$('#suggestions').hidden=true;$('#search').setAttribute('aria-expanded','false');}});
document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('#search').value=b.dataset.query;runSearch();$('#search').focus();});
document.querySelectorAll('aside input,aside select').forEach(e=>e.addEventListener('change',requestRecommendations));
document.querySelectorAll('[data-tempo]').forEach(b=>b.onclick=()=>{const [lo,hi]=b.dataset.tempo.split(',');$('#bpm-min').value=lo;$('#bpm-max').value=hi;requestRecommendations();});
$('#reset').onclick=()=>{$('#bpm-min').value=0;$('#bpm-max').value=250;for(const id of ['mood','voice','genre'])$('#'+id).value='';for(const id of ['acoustic','clean'])$('#'+id).checked=false;$('#other-artists').checked=true;requestRecommendations();};
$('#results').onclick=e=>{const s=e.target.closest('[data-save]'),t=e.target.closest('[data-seed]');if(t)selectSong(displayed[Number(t.dataset.seed)]);if(s){const track=displayed[Number(s.dataset.save)],index=saved.findIndex(t=>t[0]===track[0]);if(index>=0){saved.splice(index,1);toast('Removed from your collection');}else{saved.push(track);toast('Saved to your collection');}updateSaved();if(collectionView)showTracks(saved);else showTracks(displayed);}};
$('#saved-nav').onclick=()=>{collectionView=true;recommendId++;$('#seed').hidden=true;$('#results-title').textContent='Your little collection.';showTracks(saved);$('.discovery').scrollIntoView({behavior:'smooth',block:'start'});};
function showInfo(title,html){$('#info-content').innerHTML=`<h2>${title}</h2>${html}`;$('#info').showModal();}
async function method(){let report;try{report=await fetch('./model-report.json').then(r=>r.json());}catch{}showInfo('Good company for your favorite song.',`<p>Undertone compares nine real audio features: tempo, energy, valence, danceability, acousticness, instrumentalness, speechiness, loudness, and liveness. A standardized, weighted nearest-neighbor model finds the closest recordings. Up to two tracks per artist keep discoveries varied.</p><p>We compare four candidate metrics using genre overlap on an artist-separated validation split, then evaluate the winner on a held-out test split.${report?` The selected metric is <b>${escape(report.selected)}</b>; test genre overlap@10 is <b>${(report.test_genre_overlap_at_10*100).toFixed(1)}%</b>.`:''} This measures genre overlap, not the chance you will enjoy a song.</p><p>Mood is a simple description derived from energy and valence. “Melancholic” means low valence and lower energy. It is not a trained emotion classifier.</p><p>Male, female, and mixed lead filters use a limited editorial list of artists' usual lead vocals. They are artist-level hints and can be wrong for individual tracks. Collaborations and unlisted artists stay unknown. Instrumental means an instrumentalness estimate of at least 0.9. No singer gender is inferred from audio.</p><p>This historical catalogue does not cover every release. BPM is estimated and may reflect half-time or double-time. No audio is hosted; Listen opens Spotify, which may require an account or have regional restrictions.</p><p>Dataset: <a target="_blank" rel="noopener" href="https://huggingface.co/datasets/maharshipandya/spotify-tracks-dataset">Maharshi Pandya’s Spotify Tracks Dataset</a>, pinned to revision 635b034, declared BSD license. <a href="./model-report.json" target="_blank">Read the model report ↗</a></p>`);}
$('#about').onclick=method;$('#method').onclick=method;$('#privacy').onclick=()=>showInfo('Your music, your business.','<p>Search and recommendations run locally in your browser. Search terms and saved songs are not sent to an application server. Your collection is stored in this browser’s local storage. Clear site data to remove it.</p><p>The host receives normal page and catalogue requests. Google Fonts receives font requests. Spotify receives a request only when you open a Listen link. There are no analytics or advertising trackers.</p>');$('.dialog-close').onclick=()=>$('#info').close();$('#info').onclick=e=>{if(e.target===$('#info')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
updateSaved();worker.postMessage({type:'load'});
